def merge_sort(arr):
    def merge(left, right):
        merged = []
        while left and right:
            if left[0] <= right[0]:
                merged.append(left.pop(0))
            else:
                merged.append(right.pop(0))
        merged.extend(left)
        merged.extend(right)
        return merged
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def n_queens(n):
    def is_safe(row, col):
        for i in range(row):
            if col == cols[i] or abs(row - i) == abs(col - cols[i]):
                return False
        return True
    def solve(row, cols):
        if row == n:
            solutions.append(cols[:])
            return
        for col in range(n):
            if is_safe(row, col):
                cols[row] = col
                solve(row + 1, cols)
                cols[row] = -1
    solutions = []
    cols = [-1] * n
    solve(0, cols)
    return solutions

def gnome_sort(a):
    i = 0
    while i < len(a):
        if i == 0 or a[i - 1] <= a[i]:
            i += 1
        else:
            a[i], a[i - 1] = (a[i - 1], a[i])
            i -= 1
    return a

def comb_sort(arr):
    gap = len(arr)
    while gap > 1:
        gap = int(gap / 1.3)
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = (arr[i + gap], arr[i])
    return arr

def cocktail_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = (arr[j + 1], arr[j])
        for j in range(n - i - 1, 0, -1):
            if arr[j] < arr[j - 1]:
                arr[j], arr[j - 1] = (arr[j - 1], arr[j])
    return arr

def radix_sort(nums):
    if not nums:
        return []
    max_num = max(nums)
    for digit in range(3):
        buckets = [[] for _ in range(10)]
        for num in nums:
            buckets[num // 10 ** digit % 10].append(num)
        nums = [num for bucket in buckets for num in bucket]
    return nums

def bst_insert(root, key):
    if root is None:
        return Node(key)
    if key < root.val:
        root.left = bst_insert(root.left, key)
    else:
        root.right = bst_insert(root.right, key)
    return root

def interpolation_search(arr, target):
    low = 0
    high = len(arr) - 1
    while low <= high and target >= arr[low] and (target <= arr[high]):
        if low == high:
            if arr[low] == target:
                return low
            return -1
        pos = low + int((target - arr[low]) * (high - low) / (arr[high] - arr[low]))
        if arr[pos] == target:
            return pos
        if arr[pos] < target:
            low = pos + 1
        else:
            high = pos - 1
    return -1

def running_maximum(nums):
    if not nums:
        return []
    max_so_far = nums[0]
    result = [max_so_far]
    for num in nums[1:]:
        max_so_far = max(max_so_far, num)
        result.append(max_so_far)
    return result

def bucket_sort(arr):
    if not arr:
        return []
    max_val = max(arr)
    buckets = [[] for _ in range(max_val + 1)]
    for num in arr:
        buckets[num].append(num)
    sorted_arr = []
    for bucket in buckets:
        sorted_arr.extend(bucket)
    return sorted_arr

def kth_smallest(lst, k):
