def jump_search(arr, target):
    step = 1
    while step < len(arr) and arr[step] <= target:
        if arr[step] == target:
            return step
        step *= 2
    step = step // 2
    while step < len(arr) and arr[step] <= target:
        if arr[step] == target:
            return step
        step += 1
    return -1

def level_order_traversal(root):
    if not root:
        return []
    queue = [root]
    levels = []
    while queue:
        level = [node.val for node in queue]
        levels.append(level)
        queue = [child for node in queue for child in (node.left, node.right) if child]
    return levels

def is_same_tree(root1, root2):
    if root1 is None and root2 is None:
        return True
    if root1 is None or root2 is None:
        return False
    return root1.val == root2.val and is_same_tree(root1.left, root2.left) and is_same_tree(root1.right, root2.right)

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = (slow.next, fast.next.next)
        if slow == fast:
            return True
    return False

def delete_node(head, value):
    if head is None:
        return None
    if head.val == value:
        return head.next
    current = head
    while current.next is not None and current.next.val != value:
        current = current.next
    if current.next is not None:
        current.next = current.next.next
    return head

def nth_from_end(head, n):
    slow, fast = (head, head)
    for _ in range(n):
        if fast is None:
            return None
        fast = fast.next
    while fast is not None:
        slow, fast = (slow.next, fast.next)
    return slow

def postorder_traversal(node):
    if not node:
        return []
    return postorder_traversal(node.left) + postorder_traversal(node.right) + [node.val]

def count_leaves(node):
    if node is None:
        return 0
    return count_leaves(node.left) + count_leaves(node.right) + (node.left is None and node.right is None)

def middle_node(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def heap_pop(heap):
    if not heap:
        raise ValueError('Heap is empty')
    heap[0], heap[-1] = (heap[-1], heap[0])
    last_element = heap.pop()
    g = 0
    while g * 2 + 1 < len(heap):
        child = g * 2 + 1
        if child + 1 < len(heap) and heap[child + 1] < heap[child]:
            child += 1
        if heap[g] > heap[child]:
            heap[g], heap[child] = (heap[child], heap[g])
            g = child
        else:
            break
    return last_element

def merge_linked_lists(head1, head2):
    if head1 is None:
        return head2
    if head2 is None:
        return head1
    if head1.val < head2.val:
        head1.next = merge_linked_lists(head1.next, head2)
        return head1
    else:
        head2.next = merge_linked_lists(head1, head2.next)
        return head2

