def heap_push(heap, item):
    heap.append(item)
    g = len(heap) - 1
    while g > 0 and heap[(g - 1) // 2] > heap[g]:
        heap[g], heap[(g - 1) // 2] = (heap[(g - 1) // 2], heap[g])
        g = (g - 1) // 2

def union_sets(parent, a, b):
    root_a = a
    root_b = b
    while parent[root_a] != root_a:
        root_a = parent[root_a]
    while parent[root_b] != root_b:
        root_b = parent[root_b]
    if root_a != root_b:
        parent[root_b] = root_a

def build_min_heap(data):
    def heapify(data, i, n):
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and data[left] < data[smallest]:
            smallest = left
        if right < n and data[right] < data[smallest]:
            smallest = right
        if smallest != i:
            data[i], data[smallest] = (data[smallest], data[i])
            heapify(data, smallest, n)
    n = len(data)
    for i in range(n // 2 - 1, -1, -1):
        heapify(data, i, n)
    return data

def dfs(graph, start):
    visited = set()
    result = []
    def dfs_recursive(node):
        if node in visited:
            return
        visited.add(node)
        result.append(node)
        for neighbour in graph[node]:
            dfs_recursive(neighbour)
    dfs_recursive(start)
    return result

def find_set(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def is_cyclic(graph):
    visited = set()
    on_stack = set()
    def dfs(node):
        if node in on_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        on_stack.add(node)
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        on_stack.remove(node)
        return False
    for node in graph:
        if dfs(node):
            return True
    return False

def subset_sum(nums, target):
    def helper(i, total):
        if i == len(nums) or total == target:
            return total == target
        return helper(i + 1, total + nums[i]) or helper(i + 1, total)
    return helper(0, 0)

def topological_sort(graph):
    in_degree = {v: 0 for v in graph}
    for v in graph:
        for u in graph[v]:
            in_degree[u] += 1
    queue = [v for v in graph if in_degree[v] == 0]
    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return result

def evaluate_postfix(tokens):
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            stack.append(int(token))
    return stack[0]

def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(1, capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

def coin_change_ways(coin_values, amount):
    ways = [0] * (amount + 1)
    ways[0] = 1
    for coin in coin_values:
        for i in range(coin, amount + 1):
            ways[i] += ways[i - coin]
    return ways[amount]

def josephus(n, k):
    if n == 1:
        return 1
    else:
        return (josephus(n - 1, k) + k - 1) % n + 1

