def is_valid_date(year, month, day):
    is_leap_year = year % 4 == 0 and year % 100 != 0 or year % 400 == 0
    if month in [1, 3, 5, 7, 8, 10, 12] and 1 <= day <= 31:
        return True
    elif month in [4, 6, 9, 11] and 1 <= day <= 30:
        return True
    elif month == 2 and is_leap_year and (1 <= day <= 29):
        return True
    elif month == 2 and (not is_leap_year) and (1 <= day <= 28):
        return True
    else:
        return False

def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    return all((s.index(c) == t.index(d) for c, d in zip(s, t)))

def tic_tac_toe_winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != ' ':
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] != ' ':
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] != ' ':
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != ' ':
        return board[0][2]
    return None

def zigzag_conversion(s, n):
    if n <= 1:
        return s
    rows = [[] for _ in range(n)]
    dir = 1
    row = 0
    for char in s:
        rows[row].append(char)
        row += dir
        if row == n - 1 or row == 0:
            dir *= -1
    return ''.join((''.join(row) for row in rows))

def find_substring(string, substring):
    if not substring:
        return 0
    for i in range(len(string)):
        if string[i:i + len(substring)] == substring:
            return i
    return -1

def day_of_year(year, month, day):
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month > 2 and (year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)):
        month_days[1] += 1
    return sum(month_days[:month - 1]) + day

def remove_key(d, k):
    if k in d:
        del d[k]
    return d

def string_permutations(s):
    if len(s) == 0:
        return ['']
    result = []
    for i in range(len(s)):
        for perm in string_permutations(s[:i] + s[i + 1:]):
            result.append(s[i] + perm)
    return result

def top_k_frequent(nums, k):
    counter = {}
    for num in nums:
        if num in counter:
            counter[num] += 1
        else:
            counter[num] = 1
    sorted_counter = sorted(counter.items(), key=lambda x: x[1], reverse=True)
    return [x[0] for x in sorted_counter[:k]]

def count_vowels_consonants(s):
    vowels = 'aeiouAEIOU'
    return (sum((1 for char in s if char in vowels)), sum((1 for char in s if char.isalpha() and char not in vowels)))

def first_duplicate(lst):
    seen = set()
    for num in lst:
        if num in seen:
            return num
        seen.add(num)
    return -1

def rotate_left(lst, k):
    k %= len(lst)
    return lst[k:] + lst[:k]

def count_substring(string, substring):
    count = 0
    for i in range(len(string) - len(substring) + 1):
        if string[i:i + len(substring)] == substring:
            count += 1
    return count

def compress_string(s):
    if not s:
        return s
    compressed = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1
    compressed.append(s[-1] + str(count))
    return ''.join(compressed)

def leaders(arr):
    if not arr:
        return []
    max_so_far = arr[-1]
    leaders = [max_so_far]
    for i in range(len(arr) - 2, -1, -1):
        if arr[i] > max_so_far:
            max_so_far = arr[i]
            leaders.append(max_so_far)
    return leaders[::-1]

def second_smallest(nums):
