def valid_palindrome(s):
    s = ''.join(filter(str.isalnum, s)).lower()
    return s == s[::-1]

def string_length(s):
    count = 0
    for char in s:
        count += 1
    return count

def combinations(lst, k):
    if k == 0:
        return [[]]
    elif k == len(lst):
        return [lst]
    else:
        result = []
        for i, element in enumerate(lst):
            for combination in combinations(lst[i + 1:], k - 1):
                result.append([element] + combination)
        return result

def is_amicable(a, b):
    def sum_of_divisors(n):
        return sum([i for i in range(1, n) if n % i == 0])
    return sum_of_divisors(a) == b and sum_of_divisors(b) == a

def longest_common_substring(s1, s2):
    m, n = (len(s1), len(s2))
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    longest = 0
    end = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > longest:
                    longest = dp[i][j]
                    end = i
            else:
                dp[i][j] = 0
    return s1[end - longest:end]

def primes_between(low, high):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True
    return [n for n in range(low, high + 1) if is_prime(n)]

def next_greater_element(nums):
    stack = []
    result = [-1] * len(nums)
    for i in range(len(nums)):
        while stack and nums[i] > nums[stack[-1]]:
            result[stack.pop()] = nums[i]
        stack.append(i)
    return result

def largest_prime_factor(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n if n > 1 else i

def tribonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        a, b, c = (0, 1, 1)
        for _ in range(3, n + 1):
            a, b, c = (b, c, a + b + c)
        return c

def pairwise_swap(lst):
    for i in range(0, len(lst) - 1, 2):
        lst[i], lst[i + 1] = (lst[i + 1], lst[i])
    return lst

def product_of_digits(n):
    product = 1
    while n > 0:
        product *= n % 10
        n //= 10
    return product

def equilibrium_index(nums):
    total_sum = sum(nums)
    left_sum = 0
    for i, num in enumerate(nums):
        total_sum -= num
        if left_sum == total_sum:
            return i
        left_sum += num
    return -1

def search_insert(nums, target):
    start, end = (0, len(nums) - 1)
    while start <= end:
        mid = (start + end) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return start

def is_strong_number(num):
    def factorial(n):
        return 1 if n == 0 else n * factorial(n - 1)
    return sum((factorial(int(digit)) for digit in str(num))) == num

def first_n_primes(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def is_fibonacci(n):
    if n < 2:
        return True
    a, b = (0, 1)
    while b < n:
        a, b = (b, a + b)
    return b == n

def npr(n, r):
    fact = lambda x: 1 if x == 0 else x * fact(x - 1)
    return fact(n) // fact(n - r)

def sphere_volume(radius):
    pi = 3.14
    return 4 / 3 * pi * radius ** 3

def first_occurrence(lst, target):
    low, high = (0, len(lst) - 1)
    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == target:
            if mid == 0 or lst[mid - 1] < target:
                return mid
            high = mid - 1
        elif lst[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def is_magic_square(matrix):
    n = len(matrix)
    if n < 2:
        return True
    target_sum = sum(matrix[0])
    for row in matrix:
        if sum(row) != target_sum:
            return False
    for col in range(n):
        if sum((matrix[row][col] for row in range(n))) != target_sum:
            return False
    if sum((matrix[i][i] for i in range(n))) != target_sum or sum((matrix[i][n - i - 1] for i in range(n))) != target_sum:
        return False
    return True

def ternary_search(lst, target):
    l, r = (0, len(lst) - 1)
    while l <= r:
        mid1 = l + (r - l) // 3
        mid2 = r - (r - l) // 3
        if lst[mid1] == target:
            return mid1
        elif lst[mid2] == target:
            return mid2
        if target < lst[mid1]:
            r = mid1 - 1
        elif target > lst[mid2]:
            l = mid2 + 1
        else:
            l = mid1 + 1
            r = mid2 - 1
    return -1

def pigeonhole_sort(arr):
    if not arr:
        return []
    min_val = min(arr)
    max_val = max(arr)
    range_val = max_val - min_val + 1
    holes = [0] * range_val
    for num in arr:
        holes[num - min_val] += 1
    sorted_arr = []
    for i in range(range_val):
        sorted_arr.extend([i + min_val] * holes[i])
    return sorted_arr

def binary_gap(n):
    binary_str = bin(n)[2:]
    current_gap = 0
    max_gap = 0
    for bit in binary_str:
        if bit == '1':
            if current_gap > max_gap:
                max_gap = current_gap
            current_gap = 1
        else:
            current_gap += 1
    return max_gap

def sort_colors(A):
    i = 0
    j = len(A) - 1
    k = 0
    while k <= j:
        if A[k] == 0:
            A[k], A[i] = (A[i], A[k])
            i += 1
            k += 1
        elif A[k] == 2:
            A[k], A[j] = (A[j], A[k])
            j -= 1
        else:
            k += 1
    return A

def min_path_sum(grid):
    for i in range(1, len(grid)):
        grid[i][0] += grid[i - 1][0]
    for j in range(1, len(grid[0])):
        grid[0][j] += grid[0][j - 1]
    for i in range(1, len(grid)):
        for j in range(1, len(grid[0])):
            grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])
    return grid[-1][-1]

def binary_gray(binary):
    gray = binary[0]
    for i in range(1, len(binary)):
        gray += str(int(binary[i]) ^ int(binary[i - 1]))
    return gray

def gcd_of_list(lst):
    def gcd(a, b):
        while b:
            a, b = (b, a % b)
        return a
    result = lst[0]
    for num in lst[1:]:
        result = gcd(result, num)
    return result

def binary_insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        low, high = (0, i - 1)
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] > key:
                high = mid - 1
            else:
                low = mid + 1
        arr = arr[:low] + [key] + arr[low:i] + arr[i + 1:]
    return arr

def heap_sort(a):
    def heapify(n, i):
        largest = i
        l = 2 * i + 1
        r = 2 * i + 2
        if l < n and a[i] < a[l]:
            largest = l
        if r < n and a[largest] < a[r]:
            largest = r
        if largest != i:
            a[i], a[largest] = (a[largest], a[i])
            heapify(n, largest)
    n = len(a)
    for i in range(n // 2 - 1, -1, -1):
        heapify(n, i)
    for i in range(n - 1, 0, -1):
        a[i], a[0] = (a[0], a[i])
        heapify(i, 0)

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    visited = set()
    while visited != set(graph):
        nearest = min(((distances[node], node) for node in graph if node not in visited))[1]
        visited.add(nearest)
        for neighbour, weight in graph[nearest].items():
            distances[neighbour] = min(distances[neighbour], distances[nearest] + weight)
    return distances
